//! What setting a bridge up writes: Synapse's registration file, and the app's config file
//! (`comp-host --config-file`), which [`Config::from_lookup`] reads back.

use crate::config::Config;

pub fn registration_yaml(cfg: &Config, appservice_url: &str) -> String {
    format!(
        "# Generated by `holon matrix init`. Contains secrets: keep it private.\n\
         id: holon-agents\n\
         url: {appservice_url}\n\
         as_token: {}\n\
         hs_token: {}\n\
         sender_localpart: holon-bridge\n\
         rate_limited: false\n\
         namespaces:\n  \
           users:\n    \
             - exclusive: true\n      \
               regex: '@agent-.*:{}'\n  \
           aliases: []\n  \
           rooms: []\n",
        cfg.as_token,
        cfg.hs_token,
        cfg.server_name.replace('.', "\\.")
    )
}

/// `key = value` lines; it holds the four secrets, so it is written 0600 and never logged.
pub fn config_file(cfg: &Config) -> String {
    let mut s =
        String::from("# Generated by `holon matrix init`. Contains secrets: keep it private.\n");
    for (k, v) in cfg.entries() {
        s.push_str(&format!("{k} = {v}\n"));
    }
    s
}

#[cfg(test)]
mod tests {
    use super::*;

    fn cfg() -> Config {
        Config {
            homeserver: "http://x".into(),
            server_name: "node.tailnet.ts.net".into(),
            as_token: "AS".into(),
            hs_token: "HS".into(),
            runtime_url: "http://r".into(),
            runtime_token: "t".into(),
            owner: "@mark:node.tailnet.ts.net".into(),
            admin_token: "x".into(),
            history_chars: 3000,
            jev_key: None,
        }
    }

    #[test]
    fn the_registration_claims_exactly_the_agent_namespace_and_carries_both_tokens() {
        let cfg = cfg();
        let y = registration_yaml(&cfg, "http://100.64.0.2:9009");
        assert!(y.contains("url: http://100.64.0.2:9009"));
        assert!(y.contains("as_token: AS") && y.contains("hs_token: HS"));
        assert!(y.contains(r"regex: '@agent-.*:node\.tailnet\.ts\.net'"), "{y}");
        assert!(y.contains("exclusive: true") && y.contains("sender_localpart: holon-bridge"));
        assert!(y.contains("aliases: []"), "no aliases are claimed");
    }

    #[test]
    fn the_config_file_reads_back_as_the_same_config() {
        let text = config_file(&cfg());
        let lines: Vec<(String, String)> = text
            .lines()
            .filter(|l| !l.starts_with('#'))
            .filter_map(|l| l.split_once(" = "))
            .map(|(k, v)| (k.to_string(), v.to_string()))
            .collect();
        let back =
            Config::from_lookup(|k| lines.iter().find(|(n, _)| n == k).map(|(_, v)| v.clone()))
                .unwrap();
        assert_eq!(back.entries(), cfg().entries());
    }
}
